import pandas as pd
import numpy as np
import html
import json
from pathlib import Path
from datetime import datetime

DATA = Path('/app/benchmark/data.csv')
OUT = Path('/app/output/final_report.html')
OUT.parent.mkdir(parents=True, exist_ok=True)

df = pd.read_csv(DATA)
df['launch_year'] = df['OBJECT_ID'].astype(str).str.extract(r'^(\d{4})')[0].astype(int)
df['epoch_dt'] = pd.to_datetime(df['EPOCH'], errors='coerce')

# Orbit classification by MEAN_MOTION; requested LEO cutoff is explicit (>14 rev/day).
def classify_regime(mean_motion: float) -> str:
    if mean_motion > 14:
        return 'LEO'
    if 0.95 <= mean_motion <= 1.05:
        return 'GEO'
    if 2 < mean_motion <= 14:
        return 'MEO'
    return 'HEO'

df['regime'] = df['MEAN_MOTION'].map(classify_regime)
df['is_starlink'] = df['OBJECT_NAME'].str.upper().str.startswith('STARLINK')

def constellation(name: str) -> str:
    n = str(name).upper().strip()
    if n.startswith('STARLINK'):
        return 'Starlink'
    if n.startswith('ONEWEB'):
        return 'OneWeb'
    if n.startswith('KUIPER'):
        return 'Kuiper'
    if n.startswith('HULIANWANG'):
        return 'Hulianwang'
    if n.startswith('YAOGAN'):
        return 'Yaogan'
    if n.startswith('COSMOS') or n.startswith('KOSMOS'):
        return 'Cosmos/Kosmos'
    if n.startswith('FLOCK') or n.startswith('DOVE'):
        return 'Flock/Dove (Planet)'
    if n.startswith('QIANFAN'):
        return 'Qianfan'
    if n.startswith('IRIDIUM'):
        return 'Iridium'
    if n.startswith('LEMUR'):
        return 'Lemur (Spire)'
    if n.startswith('GEESAT'):
        return 'Geesat'
    if n.startswith('JILIN'):
        return 'Jilin'
    if n.startswith('BEIDOU') or n.startswith('BD-') or n.startswith('BEI DOU'):
        return 'BeiDou'
    if n.startswith('GSAT'):
        return 'GSAT'
    if n.startswith('ICEYE'):
        return 'ICEYE'
    if n.startswith('GPS') or n.startswith('NAVSTAR'):
        return 'GPS/Navstar'
    if n.startswith('GALILEO'):
        return 'Galileo'
    if n.startswith('GLONASS'):
        return 'GLONASS'
    if n.startswith('GLOBALSTAR'):
        return 'Globalstar'
    if n.startswith('ISS'):
        return 'ISS'
    return 'Other named satellites'

df['constellation'] = df['OBJECT_NAME'].map(constellation)

total = len(df)
leo_count = int((df['regime'] == 'LEO').sum())
leo_share = leo_count / total * 100
starlink_count = int(df['is_starlink'].sum())
starlink_share = starlink_count / total * 100
median_inc = float(df['INCLINATION'].median())
post_2020_count = int((df['launch_year'] >= 2020).sum())
post_2020_share = post_2020_count / total * 100
epoch_min = df['epoch_dt'].min()
epoch_max = df['epoch_dt'].max()
launch_min = int(df['launch_year'].min())
launch_max = int(df['launch_year'].max())

regime_order = ['LEO', 'MEO', 'GEO', 'HEO']
regime_counts = df['regime'].value_counts().reindex(regime_order, fill_value=0)
regime_shares = regime_counts / total * 100
regime_rows = [{'label': r, 'count': int(regime_counts[r]), 'share': float(regime_shares[r])} for r in regime_order]

const_counts = df['constellation'].value_counts()
top_const = const_counts.head(14)
if len(const_counts) > 14:
    top_const = pd.concat([top_const, pd.Series({'All other parsed groups': int(const_counts.iloc[14:].sum())})])
const_rows = [{'label': k, 'count': int(v), 'share': float(v/total*100)} for k, v in top_const.items()]

annual = df['launch_year'].value_counts().sort_index()
annual_rows = [{'year': int(y), 'count': int(c)} for y, c in annual.items()]
annual_starlink = df[df['is_starlink']]['launch_year'].value_counts().sort_index()
annual_non = annual.subtract(annual_starlink, fill_value=0).astype(int)
annual_stacked = [{'year': int(y), 'starlink': int(annual_starlink.get(y,0)), 'non': int(annual_non.get(y,0)), 'total': int(annual.get(y,0))} for y in annual.index]

recent = annual.loc[annual.index >= 2020]
pre2020_count = int((df['launch_year'] < 2020).sum())
peak_year = int(annual.idxmax())
peak_count = int(annual.max())
recent_peak_year = int(recent.idxmax())
recent_peak_count = int(recent.max())

cross = pd.crosstab(df['is_starlink'].map({True: 'Starlink', False: 'Non-Starlink'}), df['regime']).reindex(['Starlink','Non-Starlink']).fillna(0).astype(int)
starlink_leo_share = starlink_count / leo_count * 100
nonstar_leo_count = int(cross.loc['Non-Starlink', 'LEO'])

# Distribution bins
inc_bins = [0, 15, 35, 50, 60, 75, 85, 95, 105, 180]
inc_labels = ['0–15°', '15–35°', '35–50°', '50–60°', '60–75°', '75–85°', '85–95°', '95–105°', '>105°']
df['inc_bin'] = pd.cut(df['INCLINATION'], bins=inc_bins, labels=inc_labels, include_lowest=True, right=False)
inc_counts = df['inc_bin'].value_counts().reindex(inc_labels, fill_value=0)
inc_rows = [{'label': l, 'count': int(inc_counts[l]), 'share': float(inc_counts[l]/total*100)} for l in inc_labels]

mm_bins = [0, 0.95, 1.05, 2, 10, 14, 14.5, 15, 15.5, 17]
mm_labels = ['<0.95', '0.95–1.05', '1.05–2', '2–10', '10–14', '14–14.5', '14.5–15', '15–15.5', '>15.5']
df['mm_bin'] = pd.cut(df['MEAN_MOTION'], bins=mm_bins, labels=mm_labels, include_lowest=True, right=False)
mm_counts = df['mm_bin'].value_counts().reindex(mm_labels, fill_value=0)
mm_rows = [{'label': l, 'count': int(mm_counts[l]), 'share': float(mm_counts[l]/total*100)} for l in mm_labels]

ecc_thresholds = {
    '≤0.001': int((df['ECCENTRICITY'] <= 0.001).sum()),
    '0.001–0.01': int(((df['ECCENTRICITY'] > 0.001) & (df['ECCENTRICITY'] <= 0.01)).sum()),
    '0.01–0.1': int(((df['ECCENTRICITY'] > 0.01) & (df['ECCENTRICITY'] <= 0.1)).sum()),
    '>0.1': int((df['ECCENTRICITY'] > 0.1).sum()),
}
ecc_rows = [{'label': k, 'count': v, 'share': float(v/total*100)} for k, v in ecc_thresholds.items()]

polar_count = int(df['INCLINATION'].between(80, 100, inclusive='both').sum())
retro_count = int((df['INCLINATION'] > 90).sum())
high_ecc_count = int((df['ECCENTRICITY'] > 0.1).sum())
very_high_ecc_count = int((df['ECCENTRICITY'] > 0.25).sum())

# helpers
palette = {
    'navy': '#10233f', 'blue': '#246bfe', 'sky': '#55b7ff', 'cyan': '#1aa6a6',
    'green': '#34a853', 'amber': '#f59e0b', 'red': '#e24a4a', 'purple': '#7c3aed',
    'gray': '#64748b', 'light': '#eef5ff', 'grid': '#d9e2ef', 'ink': '#14213d'
}
chart_colors = ['#246bfe','#55b7ff','#1aa6a6','#7c3aed','#f59e0b','#34a853','#e24a4a','#8b5cf6','#0f766e','#f97316','#475569','#94a3b8','#0891b2','#a855f7','#cbd5e1']

def fmt_int(x): return f"{int(x):,}"
def fmt_pct(x, dec=1): return f"{x:.{dec}f}%"
def fmt_num(x, dec=2): return f"{x:.{dec}f}"
def esc(s): return html.escape(str(s))

def bar_svg(rows, width=760, height=360, left=168, right=32, top=24, bottom=44, max_items=None, value_key='count', pct=True, colors=None):
    data = rows[:max_items] if max_items else rows
    maxv = max(r[value_key] for r in data) if data else 1
    plot_w = width-left-right
    row_h = (height-top-bottom)/len(data)
    svg = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="bar chart">']
    for i in range(6):
        x = left + plot_w * i/5
        svg.append(f'<line x1="{x:.1f}" y1="{top}" x2="{x:.1f}" y2="{height-bottom}" stroke="{palette["grid"]}" stroke-width="1"/>')
    for i, r in enumerate(data):
        y = top + i*row_h + row_h*0.18
        h = row_h*0.58
        w = plot_w * r[value_key]/maxv if maxv else 0
        color = colors[i % len(colors)] if colors else chart_colors[i % len(chart_colors)]
        svg.append(f'<text x="{left-12}" y="{y+h*0.68:.1f}" text-anchor="end" class="axis-label">{esc(r["label"])}</text>')
        svg.append(f'<rect x="{left}" y="{y:.1f}" width="{w:.1f}" height="{h:.1f}" rx="5" fill="{color}"/>')
        label = fmt_int(r[value_key]) + (f' · {fmt_pct(r["share"])}' if pct and 'share' in r else '')
        tx = min(left+w+8, width-right-96)
        svg.append(f'<text x="{tx:.1f}" y="{y+h*0.68:.1f}" class="value-label">{label}</text>')
    svg.append('</svg>')
    return ''.join(svg)

def regime_donut(rows, width=420, height=320):
    cx, cy, r = 165, 158, 104
    circ = 2*np.pi*r
    offset = 0
    svg = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="orbital regime donut chart">']
    svg.append(f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="#e6eef8" stroke-width="44"/>')
    for i, row in enumerate(rows):
        dash = circ * row['share']/100
        color = chart_colors[i]
        svg.append(f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="{color}" stroke-width="44" stroke-dasharray="{dash:.2f} {circ-dash:.2f}" stroke-dashoffset="{-offset:.2f}" transform="rotate(-90 {cx} {cy})"/>')
        offset += dash
    svg.append(f'<text x="{cx}" y="{cy-5}" text-anchor="middle" class="donut-main">{fmt_pct(leo_share)}</text>')
    svg.append(f'<text x="{cx}" y="{cy+24}" text-anchor="middle" class="donut-sub">LEO share</text>')
    lx, ly = 310, 78
    for i, row in enumerate(rows):
        y = ly + i*38
        svg.append(f'<rect x="{lx}" y="{y-13}" width="14" height="14" rx="3" fill="{chart_colors[i]}"/>')
        svg.append(f'<text x="{lx+22}" y="{y}" class="legend-label">{row["label"]}</text>')
        svg.append(f'<text x="{lx+82}" y="{y}" class="legend-value">{fmt_int(row["count"])} ({fmt_pct(row["share"])})</text>')
    svg.append('</svg>')
    return ''.join(svg)

def launch_svg(rows, width=980, height=440):
    left, right, top, bottom = 58, 28, 28, 64
    plot_w, plot_h = width-left-right, height-top-bottom
    maxv = max(r['total'] for r in rows)
    miny, maxy = min(r['year'] for r in rows), max(r['year'] for r in rows)
    years = [r['year'] for r in rows]
    xstep = plot_w/(len(rows)-1)
    def x_for_idx(i): return left + i*xstep
    def y_for(v): return top + plot_h - (v/maxv)*plot_h
    svg = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="active satellites by launch year">']
    # grid
    for i in range(6):
        v = maxv*i/5
        y = y_for(v)
        svg.append(f'<line x1="{left}" y1="{y:.1f}" x2="{width-right}" y2="{y:.1f}" stroke="{palette["grid"]}"/>')
        svg.append(f'<text x="{left-10}" y="{y+4:.1f}" text-anchor="end" class="axis-label">{int(v):,}</text>')
    # shaded post-2020
    idx2020 = years.index(2020) if 2020 in years else 0
    x2020 = x_for_idx(idx2020) - xstep/2
    svg.append(f'<rect x="{x2020:.1f}" y="{top}" width="{width-right-x2020:.1f}" height="{plot_h}" fill="#e9f4ff" opacity="0.85"/>')
    svg.append(f'<text x="{x2020+12:.1f}" y="{top+20}" class="annotation">2020+ launches: {fmt_int(post_2020_count)} active satellites ({fmt_pct(post_2020_share)})</text>')
    # bars stacked
    bar_w = max(3, min(13, xstep*0.68))
    for i, r in enumerate(rows):
        x = x_for_idx(i) - bar_w/2
        star_h = (r['starlink']/maxv)*plot_h
        non_h = (r['non']/maxv)*plot_h
        y_non = top + plot_h - non_h
        y_star = y_non - star_h
        if r['non']:
            svg.append(f'<rect x="{x:.1f}" y="{y_non:.1f}" width="{bar_w:.1f}" height="{non_h:.1f}" fill="#55b7ff"/>')
        if r['starlink']:
            svg.append(f'<rect x="{x:.1f}" y="{y_star:.1f}" width="{bar_w:.1f}" height="{star_h:.1f}" fill="#246bfe"/>')
    # total line
    pts = ' '.join(f'{x_for_idx(i):.1f},{y_for(r["total"]):.1f}' for i, r in enumerate(rows))
    svg.append(f'<polyline points="{pts}" fill="none" stroke="#10233f" stroke-width="3" stroke-linejoin="round"/>')
    for i, r in enumerate(rows):
        if r['year'] >= 2020 or r['year'] in [launch_min, 2010, 2015, launch_max]:
            svg.append(f'<circle cx="{x_for_idx(i):.1f}" cy="{y_for(r["total"]):.1f}" r="3.3" fill="#10233f"/>')
    # annotations peak and current partial
    peak_idx = years.index(peak_year)
    px, py = x_for_idx(peak_idx), y_for(peak_count)
    svg.append(f'<line x1="{px}" y1="{py-6}" x2="{px}" y2="{py-54}" stroke="#10233f" stroke-width="1.2"/>')
    svg.append(f'<text x="{px-8}" y="{py-62}" text-anchor="end" class="annotation strong">Peak catalog year: {peak_year}</text>')
    svg.append(f'<text x="{px-8}" y="{py-42}" text-anchor="end" class="annotation">{fmt_int(peak_count)} active satellites</text>')
    if 2026 in years:
        idx = years.index(2026); x=x_for_idx(idx); y=y_for(annual.get(2026,0))
        svg.append(f'<text x="{x-6}" y="{y-18}" text-anchor="end" class="annotation">2026 catalog entries: {fmt_int(int(annual.get(2026,0)))}</text>')
    # axes
    svg.append(f'<line x1="{left}" y1="{top+plot_h}" x2="{width-right}" y2="{top+plot_h}" stroke="#93a4bb"/>')
    tick_years = [1964, 1970, 1980, 1990, 2000, 2010, 2020, 2026]
    for ty in tick_years:
        if ty in years:
            i = years.index(ty); x = x_for_idx(i)
        else:
            # approximate using continuous year scale across existing rows
            if ty < miny or ty > maxy: continue
            # nearest index
            i = min(range(len(years)), key=lambda j: abs(years[j]-ty)); x = x_for_idx(i)
        svg.append(f'<line x1="{x:.1f}" y1="{top+plot_h}" x2="{x:.1f}" y2="{top+plot_h+6}" stroke="#93a4bb"/>')
        svg.append(f'<text x="{x:.1f}" y="{top+plot_h+26}" text-anchor="middle" class="axis-label">{ty}</text>')
    # legend
    svg.append(f'<rect x="{width-305}" y="18" width="12" height="12" fill="#246bfe"/><text x="{width-287}" y="29" class="legend-label">Starlink</text>')
    svg.append(f'<rect x="{width-205}" y="18" width="12" height="12" fill="#55b7ff"/><text x="{width-187}" y="29" class="legend-label">Non-Starlink</text>')
    svg.append(f'<line x1="{width-82}" y1="24" x2="{width-52}" y2="24" stroke="#10233f" stroke-width="3"/><text x="{width-46}" y="29" class="legend-label">Total</text>')
    svg.append('</svg>')
    return ''.join(svg)

def small_table(rows, columns):
    th = ''.join(f'<th>{esc(c[0])}</th>' for c in columns)
    body = []
    for r in rows:
        tds=[]
        for _, key, kind in columns:
            val = r[key]
            if kind == 'int': val = fmt_int(val)
            elif kind == 'pct': val = fmt_pct(val)
            elif kind == 'num': val = fmt_num(val)
            tds.append(f'<td>{esc(val)}</td>')
        body.append('<tr>' + ''.join(tds) + '</tr>')
    return f'<table><thead><tr>{th}</tr></thead><tbody>{"".join(body)}</tbody></table>'

