        if r['starlink']:
            svg.append(f'<rect x="{x:.1f}" y="{y_star:.1f}" width="{bar_w:.1f}" height="{star_h:.1f}" fill="#246bfe"/>')
    # total line
    pts = ' '.join(f'{x_for_idx(i):.1f},{y_for(r["total"]):.1f}' for i, r in enumerate(rows))
    svg.append(f'<polyline points="{pts}" fill="none" stroke="#10233f" stroke-width="3" stroke-linejoin="round"/>')
    for i, r in enumerate(rows):
        if r['year'] >= 2020 or r['year'] in [launch_min, 2010, 2015, launch_max]:
            svg.append(f'<circle cx="{x_for_idx(i):.1f}" cy="{y_for(r["total"]):.1f}" r="3.3" fill="#10233f"/>')
    # annotations peak and current partial
    peak_idx = years.index(peak_year)
    px, py = x_for_idx(peak_idx), y_for(peak_count)
    svg.append(f'<line x1="{px}" y1="{py-6}" x2="{px}" y2="{py-54}" stroke="#10233f" stroke-width="1.2"/>')
    svg.append(f'<text x="{px-8}" y="{py-62}" text-anchor="end" class="annotation strong">Peak catalog year: {peak_year}</text>')
    svg.append(f'<text x="{px-8}" y="{py-42}" text-anchor="end" class="annotation">{fmt_int(peak_count)} active satellites</text>')
    if 2026 in years:
        idx = years.index(2026); x=x_for_idx(idx); y=y_for(annual.get(2026,0))
        svg.append(f'<text x="{x-6}" y="{y-18}" text-anchor="end" class="annotation">2026 catalog entries: {fmt_int(int(annual.get(2026,0)))}</text>')
    # axes
    svg.append(f'<line x1="{left}" y1="{top+plot_h}" x2="{width-right}" y2="{top+plot_h}" stroke="#93a4bb"/>')
    tick_years = [1964, 1970, 1980, 1990, 2000, 2010, 2020, 2026]
    for ty in tick_years:
        if ty in years:
            i = years.index(ty); x = x_for_idx(i)
        else:
            # approximate using continuous year scale across existing rows
            if ty < miny or ty > maxy: continue
            # nearest index
            i = min(range(len(years)), key=lambda j: abs(years[j]-ty)); x = x_for_idx(i)
        svg.append(f'<line x1="{x:.1f}" y1="{top+plot_h}" x2="{x:.1f}" y2="{top+plot_h+6}" stroke="#93a4bb"/>')
        svg.append(f'<text x="{x:.1f}" y="{top+plot_h+26}" text-anchor="middle" class="axis-label">{ty}</text>')
    # legend
    svg.append(f'<rect x="{width-305}" y="18" width="12" height="12" fill="#246bfe"/><text x="{width-287}" y="29" class="legend-label">Starlink</text>')
    svg.append(f'<rect x="{width-205}" y="18" width="12" height="12" fill="#55b7ff"/><text x="{width-187}" y="29" class="legend-label">Non-Starlink</text>')
    svg.append(f'<line x1="{width-82}" y1="24" x2="{width-52}" y2="24" stroke="#10233f" stroke-width="3"/><text x="{width-46}" y="29" class="legend-label">Total</text>')
    svg.append('</svg>')
    return ''.join(svg)

def small_table(rows, columns):
    th = ''.join(f'<th>{esc(c[0])}</th>' for c in columns)
    body = []
    for r in rows:
        tds=[]
        for _, key, kind in columns:
            val = r[key]
            if kind == 'int': val = fmt_int(val)
            elif kind == 'pct': val = fmt_pct(val)
            elif kind == 'num': val = fmt_num(val)
            tds.append(f'<td>{esc(val)}</td>')
        body.append('<tr>' + ''.join(tds) + '</tr>')
    return f'<table><thead><tr>{th}</tr></thead><tbody>{"".join(body)}</tbody></table>'

